String format(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    // Assuming there is a default conversionPattern, otherwise it should be provided as a parameter
    String conversionPattern = "%d [%t] %-5p %c - %m%n";
    StringBuilder formattedString = new StringBuilder();

    for (int i = 0; i < conversionPattern.length(); i++) {
        char currentChar = conversionPattern.charAt(i);
        if (currentChar == '%' && i + 1 < conversionPattern.length()) {
            char nextChar = conversionPattern.charAt(++i);
            switch (nextChar) {
                case 'd': // Date
                    formattedString.append(event.getTimeStamp());
                    break;
                case 't': // Thread name
                    formattedString.append(event.getThreadName());
                    break;
                case 'p': // Log level
                    formattedString.append(event.getLevel().toString());
                    break;
                case 'c': // Logger name
                    formattedString.append(event.getLoggerName());
                    break;
                case 'm': // Log message
                    formattedString.append(event.getRenderedMessage());
                    break;
                case 'n': // Newline
                    formattedString.append(System.lineSeparator());
                    break;
                default:
                    formattedString.append(currentChar).append(nextChar);
            }
        } else {
            formattedString.append(currentChar);
        }
    }
    return formattedString.toString();
}

