private int parseEndOfLine(String headerPart, int end) {
    if (headerPart == null || end < 0 || end >= headerPart.length()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    int index = end;
    while (index < headerPart.length() - 1) {
        if (headerPart.charAt(index) == '\r' && headerPart.charAt(index + 1) == '\n') {
            return index;
        }
        index++;
    }

    // If no \r\n is found, return the length of the string as the end of line
    return headerPart.length();
}

