    // First, compute the size of the message
    int size = 0;
    try {
        size = (int) schema.getSerializedSize(message);
    } catch (Exception e) {
        throw new IOException("Error computing serialized size", e);
    }

    // Check for negative size (which should not be possible)
    if (size < 0) {
        throw new IOException("Negative serialized size: " + size);
    }

    // Write the size as a varint
    final byte[] sizeBytes = new byte[10]; // Varint could be up to 10 bytes long
    int sizeSize = ProtobufOutput.computeRawVarint32Size(size);
    ProtobufOutput.putVarInt32(size, sizeBytes, 0);
    out.write(sizeBytes, 0, sizeSize);

    // Write the message using the schema
    final CodedOutputStream codedOutput = CodedOutputStream.newInstance(out);
    try {
        schema.writeTo(codedOutput, message);
        codedOutput.flush();
    } catch (IOException e) {
        throw new IOException("Error writing message", e);
    } finally {
        try {
            codedOutput.checkNoSpaceLeft();
        } catch (IOException e) {
            throw new IOException("Error checking for space left", e);
        }
    }

    return size;
}

int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || message == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Arguments cannot be null");
    }
    try {
        int size = schema.getSerializedSize(message);
        out.write(CodedOutputStream.computeRawVarint32Size(size));
        CodedOutputStream codedOutput = CodedOutputStream.newInstance(out, buffer);
        schema.writeTo(codedOutput, message);
        codedOutput.flush();
        return size;
    } catch (IOException e) {
        throw e;
    } catch (Exception e) {
        throw new IOException("Failed to write delimited message", e);
    }
}

int writeDelimitedTo(OutputStream out,T message,Schema<T> schema,LinkedBuffer buffer) throws IOException {
    if (out == null) throw new IllegalArgumentException("OutputStream cannot be null");
    if (message == null) throw new IllegalArgumentException("Message cannot be null");
    if (schema == null) throw new IllegalArgumentException("Schema cannot be null");
    if (buffer == null) throw new IllegalArgumentException("Buffer cannot be null");

    final int size = LinkedBuffer.totalBufferSize(buffer);
    if (size >= WireFormat.MAX_VARINT_SIZE32) {
        throw new IllegalArgumentException("Message is too large to fit into a varint32 length prefix");
    }

    // Write the varint32 length prefix
    int pos = 0;
    while ((size & ~0x7F) != 0) {
        out.write((byte) ((size & 0x7F) | 0x80));
        size >>>= 7;
        pos++;
    }
    out.write((byte) size);

    // Write the message content
    schema.writeTo(out, message, buffer);

    return LinkedBuffer.totalBytesWritten(buffer);
}

