private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Type[] bounds = typeVariable.getBounds();
    if (bounds.length > 0) {
        return (Class<?>) bounds[0];
    }
    Class<?> enclosingType = targetType.getEnclosingClass();
    while (enclosingType != null) {
        Type genericSuperclass = enclosingType.getGenericSuperclass();
        if (genericSuperclass instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericSuperclass;
            TypeVariable<?>[] typeParameters = enclosingType.getTypeParameters();
            for (int i = 0; i < typeParameters.length; i++) {
                if (typeParameters[i].equals(typeVariable)) {
                    return (Class<?>) ((ParameterizedType) genericSuperclass).getActualTypeArguments()[i];
                }
            }
        }
        enclosingType = enclosingType.getEnclosingClass();
    }
    return Object.class; // default to Object if type variable cannot be resolved
}

