private static int computeUTF8Length(CharSequence str) {
    int len = 0;
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c <= 0x7F) {
            len++;
        } else if (c > 0x7F && c <= 0x7FF) {
            len += 2;
