private static String substVars(String val, Map<String, String> seen) {
    StringBuilder b = new StringBuilder();
    int start = 0;
    int end = val.indexOf("${");
    while (end != -1) {
        b.append(val.substring(start, end));
        start = end + 2;
        end = val.indexOf('}', start);
        if (end == -1) {
            throw new IllegalArgumentException("No matching close brace for ${ at " + start);
        }
        String key = val.substring(start, end);
        if (seen.containsKey(key)) {
            throw new IllegalArgumentException("Circular variable reference involving " + key);
        }
        String replacement = System.getProperty(key);
        if (replacement == null) {
            replacement = val.substring(start, end);
        } else {
            replacement = substVars(replacement, new HashMap<>(seen));
        }
        b.append(replacement);
        seen.put(key, replacement);
        start = end + 1;
        end = val.indexOf("${", start);
    }
    b.append(val.substring(start));
    return b.toString();
}

