private static String substVars(String val, Properties props) {
    StringBuilder sb = new StringBuilder();
    int current = 0;
    int start = -1;
    int end = -1;
    while (current < val.length()) {
        if (val.charAt(current) == '$' && (current + 1 < val.length()) && val.charAt(current + 1) == '{') {
            if (start != -1) {
                throw new IllegalArgumentException("Nested ${vars} not allowed [" + val + "]");
            }
            start = current + 2;
        } else if (start != -1 && val.charAt(current) == '}') {
            end = current;
            String key = val.substring(start, end);
            String subst = props.getProperty(key);
            if (subst == null) {
                throw new IllegalArgumentException("No value found for key " + key + " in properties [" + val + "]");
            }
            sb.append(val.substring(current - start + 2, start - 2)).append(subst);
            start = -1;
        } else {
            sb.append(val.charAt(current));
        }
        current++;
    }
    if (start != -1) {
        throw new IllegalArgumentException("No end token found for key starting at ";
        + start + " in string [" + val + "]");
    }
    return sb.toString();
}

