List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    if (u == null) {
        return pathSegments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return pathSegments;
    }
    // If the path is absolute, ignore the leading '/'
    int start = path.startsWith("/") ? 1 : 0;
    String[] segments = path.substring(start).split("/");
    for (String segment : segments) {
        if (!segment.isEmpty()) {
            String decodedSegment = decode ? decode(segment) : segment;
            pathSegments.add(new PathSegmentImpl(decodedSegment, false));
        }
    }
    return pathSegments;
}

String decode(String encoded) {
    try {
        return URLDecoder.decode(encoded, "UTF-8");
    } catch (UnsupportedEncodingException e) {
        throw new RuntimeException("UTF-8 encoding not supported", e);
    }
}

