public String format(final LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    try {
        StringBuilder formattedMessage = new StringBuilder();
        formattedMessage.append("Timestamp: ").append(event.timeStamp).append(" ");
        formattedMessage.append("Logger: ").append(event.getLoggerName()).append(" ");
        formattedMessage.append("Level: ").append(event.getLevel()).append(" ");
        formattedMessage.append("Message: ").append(event.getRenderedMessage());
        return formattedMessage.toString();
    } catch (Exception e) {
        return "Failed to format logging event: " + e.getMessage();
    }
}

