    }
    byte[] bytes = new byte[length];
    int bytesRead = 0;
    while (bytesRead < length) {
        int read = read(bytes, bytesRead, length - bytesRead);
        if (read == -1) {
            throw new IOException("Premature end of stream while reading string");
        }
        bytesRead += read;
    }
    return new String(bytes, StandardCharsets.UTF_8);
}

