public final byte[] toByteArray(){
    try {
        if (bufferCount == 0) {
            return new byte[0];
        } else if (bufferCount == 1) {
            return buffers[0].array();
        } else {
            int size = size();
            byte[] result = new byte[size];
            int pos = 0;
            for (int i = 0; i < bufferCount; i++) {
                byte[] b = buffers[i].array();
                System.arraycopy(b, 0, result, pos, b.length);
                pos += b.length;
            }
            return result;
        }
    } catch (Exception e) {
        throw new RuntimeException("Error converting to byte array", e);
    }
}

