public final byte[] toByteArray(){
    try {
        byte[] result = new byte[(int) size()];
        int remaining = (int) size();
        int position = 0;
        for (ByteBuffer buf : buffers) {
            int len = Math.min(buf.remaining(), remaining);
            buf.get(result, position, len);
            position += len;
            remaining -= len;
        }
        return result;
    } catch (Exception e) {
        throw new RuntimeException("Failed to convert buffer to byte array", e);
    }
}

