    V startVertex = null;
    for (E edge : edgeList) {
        V sourceVertex = graph.getEdgeSource(edge);
        V targetVertex = graph.getEdgeTarget(edge);

        if (startVertex == null) {
            path.setStartVertex(sourceVertex);
            startVertex = sourceVertex;
        }

        if (path.getEndVertex().equals(sourceVertex)) {
            path.addEdge(edge);
            path.setEndVertex(targetVertex);
        } else if (path.getEndVertex().equals(targetVertex)) {
            path.addEdge(edge);
            path.setEndVertex(sourceVertex);
        } else {
            throw new IllegalArgumentException("Edges do not form a valid connected path in the graph");
        }
    }

    if (!path.getStartVertex().equals(path.getEndVertex())) {
        throw new IllegalArgumentException("The path must form a cycle");
    }

    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return new DefaultGraphPath<>();
    }

    V startVertex = graph.getEdgeSource(edgeList.get(0));
    GraphPathImpl<V, E> path = new GraphPathImpl<>(graph, startVertex, null);

    for (E edge : edgeList) {
        path.extend(edge, graph.getEdgeTarget(edge));
    }

    return path;
}

GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    if (tour.isEmpty()) {
        return new SimplePath<>();
    }

    // Create a path builder
    PathBuilder<V, E> pathBuilder = new PathBuilder<>(graph);
    V startVertex = null;
    Map<E, V> targetMap = new HashMap<>();

    // Try to determine the path by connecting edges
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        targetMap.put(edge, target);
        // Try to find a valid start vertex
        if (startVertex == null || tour.stream().noneMatch(e -> target.equals(graph.getEdgeSource(e)))) {
            startVertex = source;
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("Cannot determine a valid start vertex for the tour");
    }

    // Build the path
    V currentVertex = startVertex;
    for (E edge : tour) {
        V nextVertex = targetMap.get(edge);
        if (nextVertex == null) {
            throw new IllegalArgumentException("Edge is not part of the tour or graph");
        }
        pathBuilder.addVertex(currentVertex);
        pathBuilder.addEdge(edge);
        currentVertex = nextVertex;
    }
    pathBuilder.addVertex(currentVertex); // Add the last vertex

    // Return the constructed path
    return pathBuilder.toPath();
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, Collections.emptyList(), 0);
    }

    List<E> pathEdges = new ArrayList<>(tour);
    V startVertex = graph.getEdgeSource(pathEdges.get(0));
    List<V> pathVertices = new ArrayList<>();
    pathVertices.add(startVertex);

    for (E edge : pathEdges) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);

        if (pathVertices.get(pathVertices.size() - 1).equals(source)) {
            pathVertices.add(target);
        } else if (pathVertices.get(pathVertices.size() - 1).equals(target)) {
            pathVertices.add(source);
        } else {
            throw new IllegalArgumentException("Edges do not form a valid path");
        }
    }

    V endVertex = pathVertices.get(pathVertices.size() - 1);

    if (startVertex.equals(endVertex) && pathVertices.size() == graph.vertexSet().size() + 1) {
        return new GraphPathImpl<>(graph, startVertex, pathEdges, pathEdges.size());
    } else {
        throw new IllegalArgumentException("Edges do not form a valid tour");
    }
}

GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return createEmptyGraphPath(graph);
    }

    DefaultGraphPath<V, E> path = new DefaultGraphPath<>();
    V startVertex = getStartVertex(edgeList, graph);

    path.setStartVertex(startVertex);
    V currentVertex = startVertex;

    for (E edge : edgeList) {
        if (!graph.containsEdge(edge)) {
            throw new IllegalArgumentException("Tour contains an edge not present in the graph");
        }
        V targetVertex = graph.getEdgeTarget(edge);
        if (graph.getEdgeSource(edge).equals(currentVertex)) {
            path.addEdge(edge);
            currentVertex = targetVertex;
        } else if (graph.getEdgeTarget(edge).equals(currentVertex)) {
            path.addEdge(edge);
            currentVertex = graph.getEdgeSource(edge);
        } else {
            throw new IllegalArgumentException("Tour edges are not connected in a valid path");
        }
    }

    if (!startVertex.equals(currentVertex)) {
        throw new IllegalArgumentException("Tour does not form a closed loop");
    }

    path.setEndVertex(currentVertex);
    return path;
}

private GraphPath<V, E> createEmptyGraphPath(Graph<V, E> graph) {
    DefaultGraphPath<V, E> emptyPath = new DefaultGraphPath<>();
    emptyPath.setStartVertex(null);
    emptyPath.setEndVertex(null);
    return emptyPath;
}

private V getStartVertex(List<E> edgeList, Graph<V, E> graph) {
    Set<V> vertices = new HashSet<>();

    for (E edge : edgeList) {
        vertices.add(graph.getEdgeSource(edge));
        vertices.add(graph.getEdgeTarget(edge));
    }

    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        int degree = graph.degreeOf(source);
        vertices.remove(source);
        if (degree != 2) {
            vertices.add(source);
        }
        V target = graph.getEdgeTarget(edge);
        degree = graph.degreeOf(target);
        vertices.remove(target);
        if (degree != 2) {
            vertices.add(target);
        }
        if (vertices.size() == 1) {
            return vertices.iterator().next();
        }
    }

    // If all vertices have degree 2, arbitrarily choose the source of the first edge.
    return graph.getEdgeSource(edgeList.get(0));
}

