private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder();
    boolean escapeMode = false;
    for (char c : input.toCharArray()) {
        if (c == '\\') {
            if (escapeMode) {
                output.append('\\');
            }
            escapeMode = !escapeMode;
            continue;
        }
        if (escapeMode) {
            switch (c) {
                case 'n':
                    output.append('\n');
                    break;
                case 't':
                    output.append('\t');
                    break;
                case 'b':
                    output.append('\b');
                    break;
                case 'r':
                    output.append('\r');
                    break;
                case 'f':
                    output.append('\f');
                    break;
                default:
                    output.append(c);
                    break;
            }
            escapeMode = false;
        } else {
            output.append(c);
        }
    }
    if (escapeMode) {
        output.append('\\');
    }
    return output.toString();
}

