private String unescapeId(String input) {
    if (input == null) {
        return null;
    }
    StringBuilder output = new StringBuilder(input.length());
    boolean isEscaped = false;
    for (int i = 0; i < input.length(); i++) {
        char currentChar = input.charAt(i);
        if (isEscaped) {
            if (currentChar == 'n') {
                output.append('\n');
            } else if (currentChar == 't') {
                output.append('\t');
            } else if (currentChar == 'b') {
                output.append('\b');
            } else if (currentChar == 'r') {
                output.append('\r');
            } else if (currentChar == 'f') {
                output.append('\f');
            } else if (currentChar == 'u') {
                if (i + 4 < input.length()) {
                    String unicode = input.substring(i + 1, i + 5);
                    try {
                        int codePoint = Integer.parseInt(unicode, 16);
                        output.append((char) codePoint);
                        i += 4;
                    } catch (NumberFormatException e) {
                        // If parsing fails, just append the characters as is
                        output.append('\\').append('u').append(unicode);
                        i += 4;
                    }
                } else {
                    // Not enough characters for a unicode sequence
                    output.append('\\').append('u');
                }
            } else {
                output.append('\\').append(currentChar);
            }
            isEscaped = false;
        } else if (currentChar == '\\') {
            isEscaped = true;
        } else {
            output.append(currentChar);
        }
    }
    return output.toString();
}

