private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (bucketsByLabel == null || labels == null || minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Invalid input parameters");
    }

    Set<Integer> bucketToMove = bucketsByLabel.get(minLabel);
    if (bucketToMove == null) {
        throw new IllegalArgumentException("Bucket with label " + minLabel + " does not exist");
    }

    Set<Integer> targetBucket = bucketsByLabel.get(0);
    if (targetBucket == null) {
        targetBucket = new HashSet<>();
        bucketsByLabel.set(0, targetBucket);
    }

    for (Integer vertex : bucketToMove) {
        if (vertex < 0 || vertex >= labels.size()) {
            throw new IllegalStateException("Vertex " + vertex + " has an invalid label index");
        }
        labels.set(vertex, 0);
        targetBucket.add(vertex);
    }

    bucketToMove.clear();
}

